import { Buffer } from "node:buffer";
export default function authorize({
  headers,
  body,
  expectedAuthorization,
  userSourceId,
  semesterSourceId,
}) {
  const expected = typeof expectedAuthorization === "string" ? expectedAuthorization.trim() : "";
  const parsed = /^Basic ([A-Za-z0-9+/]+={0,2})$/.exec(expected),
    credentials = parsed ? Buffer.from(parsed[1], "base64").toString("utf8") : "";
  if (!parsed || !/^[^:]+:.+$/.test(credentials) || /[\r\n]/.test(credentials))
    throw Error("Configure a Basic authorization secret");
  const h = Object.entries(headers || {}).filter(([k]) => k.toLowerCase() === "authorization"),
    received =
      h.length === 1 && typeof h[0][1] === "string"
        ? /^Basic +([A-Za-z0-9+/]+={0,2})$/i.exec(h[0][1].trim())
        : null,
    actual = received ? Buffer.from(received[1], "base64").toString("utf8") : "";
  let diff = credentials.length ^ actual.length;
  for (let i = 0; i < Math.max(credentials.length, actual.length); i++)
    diff |= (credentials.charCodeAt(i) || 0) ^ (actual.charCodeAt(i) || 0);
  if (diff)
    return {
      accepted: false,
      statusCode: 401,
      response: { error: "Unauthorized" },
      name: "-",
      email: "-",
      userSourceId: "-",
      semesterSourceId: "-",
    };
  if (
    typeof body?.name !== "string" ||
    !body.name.trim() ||
    typeof body?.email !== "string" ||
    !body.email.trim()
  )
    return {
      accepted: false,
      statusCode: 400,
      response: { error: "Provide name and email" },
      name: "-",
      email: "-",
      userSourceId: "-",
      semesterSourceId: "-",
    };
  for (const x of [userSourceId, semesterSourceId])
    if (typeof x !== "string" || !x.trim() || x.startsWith("YOUR_"))
      throw Error("Configure both Notion data source IDs");
  return {
    accepted: true,
    statusCode: 200,
    response: { accepted: true },
    name: body.name.trim(),
    email: body.email.trim(),
    userSourceId,
    semesterSourceId,
  };
}

