export default function semester({ output }) {
  if (
    !output ||
    !Array.isArray(output.results) ||
    output.results.length !== 1 ||
    output.has_more !== false ||
    typeof output.results[0]?.id !== "string" ||
    !output.results[0].id
  )
    throw Error("Exactly one current semester is required");
  return { semesterId: output.results[0].id };
}

