export default function user({ output, name, email, userSourceId }) {
  if (
    !output ||
    !Array.isArray(output.results) ||
    output.has_more !== false ||
    output.results.length > 1
  )
    throw Error("Ambiguous user email");
  const page = output.results[0];
  if (page && (!page.id || !page.properties?.Semesters?.id))
    throw Error("User relation property is missing");
  return {
    exists: !!page,
    userId: page?.id ?? "",
    propertyId: page?.properties?.Semesters?.id ?? "",
    parent: { data_source_id: userSourceId },
    properties: { Name: { title: [{ text: { content: name } }] }, Email: { email } },
  };
}

