export default function created({ output }) {
  if (
    typeof output?.id !== "string" ||
    !output.id ||
    typeof output.properties?.Semesters?.id !== "string" ||
    !output.properties.Semesters.id
  )
    throw Error("Created user not confirmed; inspect Notion before retry");
  return { userId: output.id, propertyId: output.properties.Semesters.id };
}

