export default function relations({ previousState, response, semesterId }) {
  let state = previousState ?? { ids: [], seen: [], cursor: null };
  if (!Array.isArray(state.ids) || !Array.isArray(state.seen))
    throw Error("Invalid relation progress");
  if (response != null) {
    if (
      response.object !== "list" ||
      !Array.isArray(response.results) ||
      typeof response.has_more !== "boolean"
    )
      throw Error("Invalid relation page");
    const ids = response.results.map((x) => {
        if (typeof x?.relation?.id !== "string" || !x.relation.id) throw Error("Invalid relation");
        return x.relation.id;
      }),
      cursor = response.has_more ? response.next_cursor : null;
    if (response.has_more && (typeof cursor !== "string" || !cursor || state.seen.includes(cursor)))
      throw Error("Invalid or repeated relation cursor");
    state = {
      ids: state.ids.concat(ids),
      seen: cursor ? state.seen.concat(cursor) : state.seen,
      cursor,
    };
  }
  const all = [semesterId, ...state.ids.filter((id) => id !== semesterId)];
  if (response != null && !state.cursor && all.length > 100)
    throw Error("Notion cannot set more than 100 relations in one request");
  return {
    state,
    more: response == null || state.cursor != null,
    cursor: state.cursor,
    properties: { Semesters: { relation: all.map((id) => ({ id })) } },
  };
}

